import React, { useState } from "react";
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import Menu from '@mui/material/Menu';
import Button from '@mui/material/Button';
import MenuItem from '@mui/material/MenuItem';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import { useLocation, Link } from 'react-router-dom';
import { palette, contentColumn } from '../styles/theme';
import RecollectionDoor from './RecollectionDoor';

import { menuItems } from './items/menuItems';

// A nav item is "current" when the path equals its url, or is a descendant of
// it. The old check was `pathname.includes(item.url)`, which matched the Home
// item ('/') on literally every page.
const isCurrent = (pathname, url) =>
  url === '/' ? pathname === '/' : pathname === url || pathname.startsWith(url + '/');

const Header = () => {
  // Which submenu, if any, is open — one index rather than a parallel array of
  // booleans, since only one can be open at a time.
  const [openIndex, setOpenIndex] = useState(null);
  const [anchorEl, setAnchorEl] = useState(null);
  const location = useLocation();

  const openSubmenu = (event, index) => {
    setAnchorEl(event.currentTarget);
    setOpenIndex(index);
  };
  const closeSubmenu = () => {
    setAnchorEl(null);
    setOpenIndex(null);
  };

  return (
    <AppBar
      position="static"
      elevation={0}
      sx={{
        backgroundColor: 'transparent',
        borderBottom: `1px solid ${palette.line}`,
        color: 'text.primary',
      }}
    >
      <Box sx={contentColumn}>
        <Toolbar
          disableGutters
          sx={{ gap: { xs: 0.25, sm: 0.5 }, flexWrap: 'wrap', minHeight: { xs: 56, sm: 72 } }}
        >
          <Typography
            component={Link}
            to="/"
            variant="h6"
            sx={{
              mr: 'auto',
              color: 'primary.main',
              textDecoration: 'none',
              fontSize: { xs: '1rem', sm: '1.15rem' },
            }}
          >
            Mario Pariona
          </Typography>

          {menuItems.map((item, index) => {
            const current = isCurrent(location.pathname, item.url);
            const hasSubmenu = Boolean(item.submenu && item.submenu.length);
            const isOpen = openIndex === index;
            return (
              <Box
                key={index}
                onMouseLeave={hasSubmenu ? closeSubmenu : undefined}
                sx={{ display: 'inline-flex' }}
              >
                <Button
                  component={Link}
                  to={item.url}
                  onMouseEnter={hasSubmenu ? (e) => openSubmenu(e, index) : closeSubmenu}
                  aria-haspopup={hasSubmenu || undefined}
                  aria-expanded={hasSubmenu ? isOpen : undefined}
                  aria-current={current ? 'page' : undefined}
                  endIcon={
                    hasSubmenu ? (
                      <KeyboardArrowDownIcon
                        sx={{
                          fontSize: '1rem !important',
                          transition: 'transform 0.2s',
                          transform: isOpen ? 'rotate(180deg)' : 'none',
                        }}
                      />
                    ) : null
                  }
                  sx={{
                    px: { xs: 1, sm: 1.5 },
                    minWidth: 0,
                    color: current || isOpen ? 'primary.main' : 'text.secondary',
                    fontWeight: current ? 700 : 500,
                    borderRadius: 0,
                    borderBottom: `2px solid ${current ? palette.gold : 'transparent'}`,
                    '& .MuiButton-endIcon': { ml: 0.25 },
                    '&:hover': { backgroundColor: 'transparent', color: 'primary.main' },
                  }}
                >
                  {item.title}
                </Button>

                {hasSubmenu && (
                  <Menu
                    id={`menu-appbar-${index}`}
                    anchorEl={anchorEl}
                    open={isOpen}
                    onClose={closeSubmenu}
                    // Left-aligned under its button rather than centre-anchored,
                    // which is what made the old panel look detached from the
                    // item that opened it.
                    anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
                    transformOrigin={{ vertical: 'top', horizontal: 'left' }}
                    disableScrollLock
                    // Keep the pointer's path from the button into the panel
                    // alive, and kill MUI's default modal backdrop/focus trap
                    // so a hover menu doesn't behave like a dialog.
                    MenuListProps={{ onMouseLeave: closeSubmenu, dense: true, sx: { py: 0.75 } }}
                    slotProps={{
                      paper: {
                        elevation: 0,
                        onMouseLeave: closeSubmenu,
                        sx: {
                          mt: 0.5,
                          minWidth: 190,
                          borderRadius: 2,
                          border: `1px solid ${palette.line}`,
                          boxShadow: '0 12px 32px rgba(15, 27, 45, 0.14)',
                          overflow: 'visible',
                          // Gold hairline along the top edge, tying the panel
                          // back to the active nav underline.
                          '&::before': {
                            content: '""',
                            position: 'absolute',
                            top: 0,
                            left: 0,
                            right: 0,
                            height: '2px',
                            backgroundColor: palette.gold,
                            borderRadius: '8px 8px 0 0',
                          },
                        },
                      },
                    }}
                  >
                    {item.submenu.map((sub, key) => {
                      const subCurrent = isCurrent(location.pathname, sub.url);
                      return (
                        <MenuItem
                          key={key}
                          component={Link}
                          to={sub.url}
                          onClick={closeSubmenu}
                          selected={subCurrent}
                          sx={{
                            mx: 0.75,
                            my: 0.15,
                            borderRadius: 1.5,
                            fontSize: '0.9rem',
                            color: subCurrent ? 'primary.main' : 'text.secondary',
                            fontWeight: subCurrent ? 700 : 500,
                            borderLeft: '2px solid transparent',
                            transition: 'border-color 0.15s, padding-left 0.15s',
                            '&.Mui-selected': { backgroundColor: 'transparent' },
                            '&:hover, &.Mui-selected:hover': {
                              backgroundColor: 'rgba(212, 168, 71, 0.10)',
                              borderLeftColor: palette.gold,
                              color: 'primary.main',
                              pl: 2.5,
                            },
                          }}
                        >
                          {sub.title}
                        </MenuItem>
                      );
                    })}
                  </Menu>
                )}
              </Box>
            );
          })}

          {/* The door into /recollection — see RecollectionDoor.js. */}
          <RecollectionDoor variant="header" />
        </Toolbar>
      </Box>
    </AppBar>
  );
};

export default Header;
