import { createTheme } from '@mui/material/styles';

// Palette deliberately shares its two anchor colours with Recollection
// (faith/journal-app) — deep navy #0f1b2d and gold #d4a847 — so that walking
// from the portfolio into /recollection reads as moving between two rooms of
// the same house rather than two unrelated sites. The portfolio stays on a
// light, warm ground; Recollection is the dark room.

export const palette = {
  navy: '#0f1b2d',
  navySoft: '#1c2f52',
  navyMuted: '#55637a',
  gold: '#d4a847',
  goldDeep: '#a8801f',
  ivory: '#faf8f3',
  surface: '#ffffff',
  line: '#e6e0d4',
};

// The centred content column, shared by the header, main, and footer. Kept in
// JS rather than as a CSS class so it composes with `sx` predictably — mixing
// the two meant per-page overrides (e.g. the header's zero bottom padding)
// depended on stylesheet ordering.
export const contentColumn = {
  width: '100%',
  maxWidth: 900,
  mx: 'auto',
  px: { xs: 2, sm: 3 },
};

const serif = '"Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif';
const sans = '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif';

const theme = createTheme({
  palette: {
    primary: {
      main: palette.navy,
      light: palette.navySoft,
      contrastText: '#ffffff',
    },
    secondary: {
      main: palette.gold,
      dark: palette.goldDeep,
      contrastText: palette.navy,
    },
    background: {
      default: palette.ivory,
      paper: palette.surface,
    },
    text: {
      primary: palette.navy,
      secondary: palette.navyMuted,
    },
    divider: palette.line,
  },
  typography: {
    fontFamily: sans,
    h1: {
      fontFamily: serif,
      fontWeight: 700,
      fontSize: 'clamp(2rem, 5vw, 2.75rem)',
      color: palette.navy,
      letterSpacing: '-0.01em',
      marginBottom: '16px',
    },
    h2: {
      fontFamily: serif,
      fontWeight: 600,
      fontSize: 'clamp(1.6rem, 4vw, 2.1rem)',
      color: palette.navy,
      letterSpacing: '-0.01em',
      marginBottom: '12px',
    },
    h3: {
      fontFamily: serif,
      fontWeight: 600,
      fontSize: '1.6rem',
      color: palette.navy,
    },
    h6: {
      fontFamily: serif,
      fontWeight: 600,
    },
    // Small caps eyebrow used above section headings, mirroring Recollection's
    // .gate-eyebrow. Registered as a variant so pages don't re-declare it.
    overline: {
      fontSize: '0.68rem',
      fontWeight: 700,
      letterSpacing: '0.22em',
      textTransform: 'uppercase',
      color: palette.goldDeep,
      lineHeight: 2,
    },
    body1: {
      fontSize: '1rem',
      lineHeight: 1.65,
      color: palette.navyMuted,
    },
    button: {
      textTransform: 'none',
      fontWeight: 600,
      letterSpacing: '0.01em',
    },
  },
  shape: {
    borderRadius: 10,
  },
  components: {
    MuiCssBaseline: {
      styleOverrides: {
        body: {
          backgroundColor: palette.ivory,
        },
      },
    },
    MuiAppBar: {
      styleOverrides: {
        root: {
          boxShadow: 'none',
        },
      },
    },
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 999,
          paddingInline: '1.4rem',
        },
        containedPrimary: {
          '&:hover': { backgroundColor: palette.navySoft },
        },
        outlinedPrimary: {
          borderColor: palette.line,
        },
      },
    },
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 12,
          border: `1px solid ${palette.line}`,
          backgroundColor: palette.surface,
          boxShadow: '0 1px 2px rgba(15, 27, 45, 0.04)',
          transition: 'box-shadow 0.25s, border-color 0.25s, transform 0.25s',
          '&:hover': {
            boxShadow: '0 10px 28px rgba(15, 27, 45, 0.10)',
            borderColor: palette.gold,
          },
        },
      },
    },
    MuiLink: {
      styleOverrides: {
        root: {
          color: palette.goldDeep,
          textDecorationColor: palette.line,
        },
      },
    },
    MuiTypography: {
      styleOverrides: {
        body1: {
          marginBottom: '8px',
        },
      },
    },
  },
});

export default theme;
