import React from 'react';
import { achievementItems } from '../components/items/achievementItems';
import { extracurricularItems } from '../components/items/extracurricularItems';
import { Typography, Box } from '@mui/material';
import AchievementTab from '../components/AchievementTab';
import PageSurface from '../components/PageSurface';

function Achievements() {
  return (
    <PageSurface eyebrow="Olympiads & awards" title="Achievements">
      <Box display="flex" flexDirection="column" gap={2}>
        {achievementItems.map((achievement, index) => (
          <AchievementTab key={index} index={index} achievement={achievement} enumerate />
        ))}
      </Box>

      {/* This content already existed in extracurricularItems.js but had no
          route pointing at it, so nothing on the site ever rendered it. */}
      <Box sx={{ mt: 6 }}>
        <Typography variant="overline" component="p">
          Outside the course
        </Typography>
        <Typography variant="h3" component="h2" sx={{ mb: 1 }}>
          Extracurricular
        </Typography>
        <Box aria-hidden sx={{ width: 48, height: 2, backgroundColor: 'secondary.main', mb: 3 }} />

        <Box display="flex" flexDirection="column" gap={2}>
          {extracurricularItems.map((item, index) => (
            <AchievementTab
              key={index}
              index={index}
              achievement={{ name: item.name, date: item.date }}
              description={item.description}
            />
          ))}
        </Box>
      </Box>
    </PageSurface>
  );
}

export default Achievements;
